sys_script_client.script:
function onSubmit() {
    var subcategory = String(g_form.getValue('subcategory'));

    // 1. Doctor Communication (121) or Lack of Empathy (125)
    // Must provide either Admission OR Appointment
    if (subcategory === '121' || subcategory === '125') {
        var admission = g_form.getValue('admission');
        var appointment = g_form.getValue('appointment');
        if (!admission && !appointment) {
            g_form.addErrorMessage('Please provide either an Admission or an Appointment record for this grievance.');
            g_form.showFieldMsg('admission', 'Provide either Admission or Appointment', 'error');
            g_form.showFieldMsg('appointment', 'Provide either Admission or Appointment', 'error');
            return false;
        }
    }

    // 2. Billing / Admin Staff Misconduct (123)
    // Must provide either Admission OR Invoice
    if (subcategory === '123') {
        var admission123 = g_form.getValue('admission');
        var invoice123 = g_form.getValue('invoice');
        if (!admission123 && !invoice123) {
            g_form.addErrorMessage('Please provide either an Admission or an Invoice record for this grievance.');
            g_form.showFieldMsg('admission', 'Provide either Admission or Invoice', 'error');
            g_form.showFieldMsg('invoice', 'Provide either Admission or Invoice', 'error');
            return false;
        }
    }
}
